/** 找不到标定时回退到画布顶边0，绝不猜测另一个动作的边界。 */
export function animationAlphaTop(sheet: string, index: number): number {
    const value = ANIMATION_ALPHA_TOP[sheet]?.[index];
    return Number.isFinite(value) && value >= 0 ? value : 0;
}
